rows:
acute = :segment{} last 7d | :avg{metric:sessionLoad}
chronic = :segment{} last 28d | :avg{metric:sessionLoad}
acwr = acute / chronic
show acwr | :value{label:"ACWR", goal:1.0}

defaults by {week} last 12w
push = :segment{effort:bench-press|overhead-press} | :sum{metric:totalVolume}
pull = :segment{effort:pull-up|pendlay-row} | :sum{metric:totalVolume}
balance = (pull / push) * 100 -> %
show push, pull | :bar{}
show balance | :timeseries{}

best_squat = :segment{effort:back-squat} last 52w | :max{metric:resistance}
weekly_top = :segment{effort:back-squat} last 8w | :max{metric:resistance} by {week}
pct_1rm = (weekly_top / best_squat) * 100 -> %
show pct_1rm | :timeseries{goal:85}

:note{note:$note} | :sum{metric:reps} by {equipment} | :bar{label:"Reps by Equipment"}

// Or using the direct segment shorthand on the note:
:segment{note:$note} | :sum{metric:reps} by {equipment} | :donut{}

bench_notes = :journal{intent:benchmark, domain:crossfit} last 12w
kb_reps = bench_notes | :sum{metric:reps, equipment:kettlebell} by {week}
bb_reps = bench_notes | :sum{metric:reps, equipment:barbell} by {week}
total_reps = kb_reps + bb_reps
show kb_reps, bb_reps | :stacked-bar{}

this_note_reps = :segment{note:$note} | :sum{metric:reps} by {equipment}
history_avg = :journal{format:for-time} last 8w | :avg{metric:reps} by {equipment}
diff_pct = ((this_note_reps - history_avg) / history_avg) * 100 -> %
show this_note_reps, history_avg | :bar{}

note_events = :segment{note:$note, intensity:high}
heavy_reps = note_events | :sum{metric:reps} by {equipment}
peak_load = note_events | :max{metric:resistance} by {equipment}
show heavy_reps | :toplist{}
